import random
import base64
from typing import List

# Generator for Base64-encoded inputs with a variety of valid structures and lengths.
# Tailored for the base64_decode fuzzer stub:
# - Prefer valid Base64 strings to hit success paths
# - Include variation in padding, line breaks, and chunk sizes
# - Keep total size <= 1024 bytes (stub truncates beyond that anyway)
# - Return bytes (UTF-8 text) suitable for FUZZ_PARAM_STR()

ALPHABET = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"


def _rand_bytes(rng: random.Random, n: int) -> bytes:
    return bytes(rng.getrandbits(8) for _ in range(n))


def _chunked(b: bytes, chunk: int, sep: bytes) -> bytes:
    if chunk <= 0:
        return b
    return sep.join(b[i:i+chunk] for i in range(0, len(b), chunk))


def _make_valid_b64_from_raw(rng: random.Random, raw: bytes, with_padding: bool = True,
                             line_breaks: bool = False) -> bytes:
    # Use standard library to ensure correctness, then optionally reflow with line breaks
    enc = base64.b64encode(raw)
    if not with_padding:
        # Strip '=' padding (valid in some decoders though RFC allows omission in some contexts)
        enc = enc.rstrip(b"=")
    if line_breaks and len(enc) > 64:
        # Insert CRLF or LF randomly at typical MIME columns
        width = rng.choice([64, 76])
        sep = rng.choice([b"\n", b"\r\n"]) if rng.random() < 0.7 else b"\n"
        enc = _chunked(enc, width, sep)
    return enc


def _make_alphabet_mapped(rng: random.Random, n: int, pad_mode: int) -> bytes:
    # Produce a string comprised of Base64 alphabet chars; may not correspond to valid blocks
    s = bytearray()
    for _ in range(n):
        s.append(ALPHABET[rng.randrange(64)])
    if pad_mode == 1:
        s += b"="
    elif pad_mode == 2:
        s += b"=="
    elif pad_mode == 3:
        # Randomly trim tail to make length % 4 in {1,2,3}
        trim = rng.randrange(1, 3)
        if len(s) > trim:
            del s[-trim:]
    return bytes(s)


def _make_edge_case(rng: random.Random) -> bytes:
    # Select edge scenarios to exercise decoder behavior
    choice = rng.randrange(8)
    if choice == 0:
        return b""  # empty input
    if choice == 1:
        return b"===="  # just padding
    if choice == 2:
        return b"A==="  # invalid padding length
    if choice == 3:
        return b"AAA="  # single padding
    if choice == 4:
        return b"AAAA"  # valid 3 zero bytes
    if choice == 5:
        # Long run of valid chars with final padding
        return b"QUFBQUFBQUFBQUFBQUFBQUFBQUFBQUFBQUFBQUFBQUFBQUFBQUFBPQ=="  # enc("A"*33) ish
    if choice == 6:
        # Include line breaks at odd places (still valid MIME form)
        raw = _rand_bytes(rng, rng.randrange(1, 128))
        return _make_valid_b64_from_raw(rng, raw, with_padding=True, line_breaks=True)
    # choice == 7
    # No padding variant (some decoders accept)
    raw = _rand_bytes(rng, rng.randrange(1, 64))
    return _make_valid_b64_from_raw(rng, raw, with_padding=False, line_breaks=False)


def _cap(b: bytes, limit: int = 1024) -> bytes:
    return b if len(b) <= limit else b[:limit]


def generate(seed: int) -> bytes:
    rng = random.Random(seed)

    # Decide a strategy mix favoring valid encodings
    strategy = rng.choices(
        population=["valid_raw", "alphabet_mapped", "edge", "mixed_blocks"],
        weights=[50, 20, 15, 15],
        k=1,
    )[0]

    if strategy == "valid_raw":
        # Generate random raw data, encode to Base64 with optional formatting
        total = rng.randrange(0, 900)  # leaves room for line breaks
        raw = _rand_bytes(rng, total)
        with_padding = rng.random() < 0.85
        line_breaks = rng.random() < 0.4
        out = _make_valid_b64_from_raw(rng, raw, with_padding=with_padding, line_breaks=line_breaks)
        return _cap(out)

    if strategy == "alphabet_mapped":
        n = rng.randrange(0, 1024)
        pad_mode = rng.randrange(4)  # 0..3
        out = _make_alphabet_mapped(rng, n, pad_mode)
        # Occasionally insert whitespace that many decoders ignore
        if rng.random() < 0.3 and len(out) > 16:
            # insert spaces/newlines every 60-76 chars
            width = rng.choice([60, 64, 76])
            sep = rng.choice([b"\n", b"\r\n", b" "])
            out = _chunked(out, width, sep)
        return _cap(out)

    if strategy == "edge":
        return _cap(_make_edge_case(rng))

    # mixed_blocks: concatenate several valid and alphabet-mapped segments
    parts: List[bytes] = []
    total_len = 0
    target = rng.randrange(64, 1024)
    while total_len < target:
        which = rng.randrange(3)
        if which == 0:
            raw = _rand_bytes(rng, rng.randrange(1, 128))
            seg = _make_valid_b64_from_raw(rng, raw, with_padding=rng.random() < 0.8,
                                           line_breaks=rng.random() < 0.3)
        elif which == 1:
            seg = _make_alphabet_mapped(rng, rng.randrange(8, 128), rng.randrange(4))
        else:
            seg = _make_edge_case(rng)
        parts.append(seg)
        total_len += len(seg)
        # Occasionally separate with whitespace
        if rng.random() < 0.25:
            parts.append(rng.choice([b"\n", b"\r\n", b" "]))
            total_len += len(parts[-1])
        if total_len > 1024:
            break
    out = b"".join(parts)
    return _cap(out)
